/**
 * Batch-translate missing polity names to Chinese via DeepSeek API.
 *
 * Reads scripts/_missing_names.json (generated by count step),
 * translates in batches of 25 names per API call,
 * merges results into public/ne/polity_names_zh.json.
 *
 * Supports resume — re-run to continue from where it left off.
 *
 * Usage:  node scripts/translate_names.cjs
 */

const fs = require('fs');
const https = require('https');
const path = require('path');

// Load .env
function loadEnv(filePath) {
  if (!fs.existsSync(filePath)) return;
  const lines = fs.readFileSync(filePath, 'utf-8').split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx).trim();
    const val = trimmed.slice(eqIdx + 1).trim();
    if (!process.env[key]) process.env[key] = val;
  }
}
loadEnv(path.join(__dirname, '..', '.env'));

const DEEPSEEK_API_KEY = process.env.DEEPSEEK_API_KEY || process.env.ANTHROPIC_API_KEY;
const MODEL = 'deepseek-chat';
const API_HOST = 'api.deepseek.com';
const API_PATH = '/v1/chat/completions';

const INPUT_FILE = 'scripts/_missing_names.json';
const OUTPUT_FILE = 'public/ne/polity_names_zh.json';
const BATCH_SIZE = 25;
const CONCURRENCY = 5;
const DELAY_MS = 500;

if (!DEEPSEEK_API_KEY) {
  console.error('DEEPSEEK_API_KEY not set.');
  process.exit(1);
}

// HTTP helper
function chatCompletion(messages) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({
      model: MODEL,
      messages,
      temperature: 0.3,
      max_tokens: 2000,
      stream: false,
    });

    const req = https.request({
      hostname: API_HOST,
      path: API_PATH,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${DEEPSEEK_API_KEY}`,
        'Content-Length': Buffer.byteLength(body),
      },
      timeout: 60000,
    }, (res) => {
      let data = '';
      res.on('data', (c) => data += c);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          if (json.error) {
            reject(new Error(`API: ${json.error.message || JSON.stringify(json.error)}`));
          } else {
            resolve(json.choices?.[0]?.message?.content || null);
          }
        } catch (e) {
          reject(new Error(`Parse: ${e.message}`));
        }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    req.write(body);
    req.end();
  });
}

const delay = (ms) => new Promise(r => setTimeout(r, ms));

function buildPrompt(names) {
  const list = names.map((n, i) => `${i + 1}. ${n}`).join('\n');
  return `请将以下英文历史政体名称翻译为中文。注意：
- 这是用于历史地图的政体名称，请使用历史学界通用的中文译名
- 如果没有通用译名，请根据字面含义和历史背景合理翻译
- 现代国家使用标准译名（如"United States"→"美国"）
- 王朝/帝国类使用"XX王朝""XX帝国"格式
- 苏丹国/酋长国等保留"苏丹国""酋长国"后缀
- 返回严格的JSON对象格式，键为英文原名，值为中文译名
- 只返回JSON，不要任何解释文字

${list}`;
}

async function translateBatch(names) {
  const prompt = buildPrompt(names);
  const messages = [
    { role: 'system', content: '你是一位精通世界历史地理的翻译专家。你只输出JSON，不输出任何其他内容。' },
    { role: 'user', content: prompt },
  ];

  for (let attempt = 0; attempt <= 2; attempt++) {
    try {
      const result = await chatCompletion(messages);
      if (!result) continue;
      // Try to extract JSON from response
      const jsonMatch = result.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const count = Object.keys(parsed).length;
        if (count > 0) return parsed;
      }
      console.warn('  Could not parse JSON from response, retry...');
    } catch (err) {
      console.warn(`  Batch translate attempt ${attempt + 1} failed:`, err.message);
      if (attempt < 2) await delay(1000);
    }
  }
  return {};
}

async function main() {
  // Load missing names
  const missing = JSON.parse(fs.readFileSync(INPUT_FILE, 'utf-8'));
  console.log(`Total missing names: ${missing.length}`);

  // Load existing name map and remove already-translated from missing list
  const nameMap = JSON.parse(fs.readFileSync(OUTPUT_FILE, 'utf-8'));
  const stillMissing = missing.filter(n => !nameMap[n]);
  console.log(`Still missing (after resume): ${stillMissing.length}`);

  if (stillMissing.length === 0) {
    console.log('All names already translated. Done.');
    return;
  }

  // Create batches
  const batches = [];
  for (let i = 0; i < stillMissing.length; i += BATCH_SIZE) {
    batches.push(stillMissing.slice(i, i + BATCH_SIZE));
  }
  console.log(`Batches: ${batches.length} (${BATCH_SIZE} names each, concurrency: ${CONCURRENCY})`);

  let totalDone = 0;
  let totalTranslated = 0;

  async function worker() {
    while (batches.length > 0) {
      const batch = batches.shift();
      if (!batch) break;
      const result = await translateBatch(batch);
      const count = Object.keys(result).length;

      // Merge into name map
      for (const [en, zh] of Object.entries(result)) {
        if (!nameMap[en]) {
          nameMap[en] = zh;
          totalTranslated++;
        }
      }

      totalDone += batch.length;
      const pct = ((totalDone / stillMissing.length) * 100).toFixed(1);
      console.log(`  Batch done: ${count}/${batch.length} translated | Total: ${totalDone}/${stillMissing.length} (${pct}%)`);

      // Save checkpoint
      if (totalTranslated % 100 < BATCH_SIZE + CONCURRENCY) {
        fs.writeFileSync(OUTPUT_FILE, JSON.stringify(nameMap, null, 2), 'utf-8');
        // Also update the missing file for resume
        const remaining = stillMissing.filter(n => !nameMap[n]);
        fs.writeFileSync(INPUT_FILE, JSON.stringify(remaining, null, 2));
        console.log(`  Saved checkpoint. ${remaining.length} remaining.`);
      }

      await delay(DELAY_MS);
    }
  }

  console.log('\nStarting translation...\n');
  const workers = Array.from({ length: CONCURRENCY }, () => worker());
  await Promise.all(workers);

  // Final save
  fs.writeFileSync(OUTPUT_FILE, JSON.stringify(nameMap, null, 2), 'utf-8');
  const finalRemaining = missing.filter(n => !nameMap[n]);
  fs.writeFileSync(INPUT_FILE, JSON.stringify(finalRemaining, null, 2));

  console.log(`\nDone!`);
  console.log(`  Translated: ${totalTranslated}`);
  console.log(`  Total name map entries: ${Object.keys(nameMap).length}`);
  console.log(`  Still missing: ${finalRemaining.length}`);
  console.log(`  Coverage: ${((missing.length - finalRemaining.length) / missing.length * 100).toFixed(1)}%`);
}

main().catch(err => { console.error('Fatal:', err); process.exit(1); });
